    "The project is unavailable. Select the project again.": "프로젝트가 없으므로 프로젝트를 다시 선택합니다.",
    "The project was saved, but activation could not be confirmed. Restart Noda; project data is preserved.": "프로젝트가 저장되었지만 활성화는 확인되지 못했습니다.Noda를 다시 시작; 프로젝트 데이터가 저장됩니다.",
    "The queue is empty": "대기열이 비어 있습니다",
    "The queue is empty. Add your first note.": "꼬리가 텅 비어있어 첫 번째 메모를 추가하십시오.",
    "The queue is full and the source text was not accepted": "꼬리가 가득 차 있고 출처 텍스트가 받아 들여지지 않았습니다.",
    "The request is outside the local project.": "이 요청은 지역 프로젝트 밖에서 나온다.",
    "The request was interrupted. You can retry it.": "요청이 중단되었습니다.당신은 그것을 철회 할 수 있습니다.",
