    "The saved folder is unavailable. Choose another project folder to continue.": "저장된 폴더가 사용할 수 없습니다. 계속하려면 다른 프로젝트 폴더를 선택합니다.",
    "The saved pairs could not be read. Select and save them again.": "저장된 커플은 읽을 수 없었습니다. 선택하고 다시 저장합니다.",
