    "The source text is saved as a note. Its title, tags, and links are still pending.": "출처 텍스트는 메모로 저장됩니다. 제목, 태그 및 링크는 여전히 기다리고 있습니다.",
    "The source text is saved. Generation did not finish. See the queue for details.": "출처 텍스트가 저장되었습니다.세대가 끝나지 않았습니다.세부 사항을 위한 꼬리를 참조하십시오.",
    "The source text is saved. Processing did not finish. You can copy the source text.": "출처 텍스트가 저장됩니다. 처리 완료되지 않았습니다. 출처 텍스트를 복사할 수 있습니다.",
    "The source text is saved. The job is queued.": "출처 텍스트가 저장되었습니다.직업은 니다.",
